-- Read of /etc/shadow by a process that has no business reading it
-- a0b40576-aad7-468e-a22c-6b3bc3206bc7
SELECT uid, time, hostname, product, user_name, process_name, process_path, cmd_line, parent_path, target_file, dst_ip, dst_port FROM ocsf_flat WHERE time >= ? AND time < ? AND class_uid = 1001 AND activity_id = 2 AND ((coalesce(target_file ILIKE '/etc/shadow' ESCAPE '\', false) OR coalesce(target_file ILIKE '/etc/gshadow' ESCAPE '\', false)) AND NOT (coalesce(process_path ILIKE '%/unix\_chkpwd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/passwd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/chpasswd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/chage' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/useradd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/usermod' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/userdel' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/groupadd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/sshd' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/login' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/su' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/sudo' ESCAPE '\', false) OR coalesce(process_path ILIKE '%/cron' ESCAPE '\', false))) ORDER BY time;
